target.css:
:root {
  --ink: #173c4b;
  --muted: #5f7b85;
  --card: #ffffff;
  --line: #d5e5e8;
  --aqua: #dff5f2;
  --teal: #147f83;
  --coral: #ff826d;
  --sand: #fff0cf;
}

* {
  box-sizing: border-box;
}

.feeding-card {
  width: 476px;
  padding: 16px;
  color: var(--ink);
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 18px;
}

.card-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  margin-bottom: 12px;
}

.title-group p,
.tank-tile p {
  margin: 0;
}

.eyebrow {
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
  line-height: 1.2;
  letter-spacing: 0.5px;
  text-transform: uppercase;
}

h2 {
  margin: 4px 0 0;
  font-size: 22px;
  line-height: 1;
}

.time-badge {
  padding: 6px 9px;
  color: var(--teal);
  background: var(--aqua);
  border-radius: 999px;
  font-size: 13px;
  font-weight: 800;
}

.tank-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  margin-bottom: 12px;
}

.tank-tile {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 10px;
  border-radius: 12px;
}

.coral-tank {
  background: var(--sand);
}

.kelp-tank {
  background: var(--aqua);
}

.tank-icon {
  display: grid;
  width: 32px;
  height: 32px;
  place-items: center;
  background: var(--card);
  border-radius: 10px;
  font-size: 18px;
}

.tank-tile strong {
  display: block;
  font-size: 13px;
  line-height: 1.15;
}

.tank-tile p {
  margin-top: 3px;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.15;
}

.route-list {
  display: grid;
  gap: 7px;
  padding: 0;
  margin: 0;
  list-style: none;
}

.route-list li {
  display: grid;
  grid-template-columns: 22px 1fr auto;
  align-items: center;
  gap: 8px;
  padding: 7px 0;
  border-bottom: 1px solid var(--line);
  font-size: 13px;
  font-weight: 600;
}

.check {
  display: grid;
  width: 22px;
  height: 22px;
  place-items: center;
  color: var(--coral);
  border: 1px solid var(--coral);
  border-radius: 7px;
  font-size: 12px;
  font-weight: 800;
}

.check.done {
  color: var(--card);
  background: var(--teal);
  border-color: var(--teal);
}

.route-time {
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 12px;
  color: var(--muted);
  font-size: 12px;
  font-weight: 700;
}

button {
  padding: 7px 10px;
  color: var(--card);
  background: var(--teal);
  border: 0;
  border-radius: 8px;
  font-size: 12px;
  font-weight: 800;
}

